/**
 * 构造动物梦境测试的原 World、角色对象与初始座位。输入为原配置、组件和调用方字段，输出为显式 fixture 值；玩家身份和手写断言由测试提供。这里只造输入，不运行阶段、完整对局、传输、归档或规则验证器。
 */
import { createAliveComponent, createCampComponent, createVotingRightComponent } from "../../../../../src/game/observation/component-presentation";
import { World } from "../../../../../src/core/domain/world";
import { Role, Camp } from "../../../../../src/core/domain/identity";
import { COMPONENT } from "../../../../../src/core/domain/components/names";
import { type RoleComponent } from "../../../../../src/core/domain/components/role";
import { createRoleComponent } from "../../../../../src/game/observation/role-presentation";
import { type AliveComponent } from "../../../../../src/core/domain/components/alive";


import { createVictoryComponent } from "../../../../../src/core/domain/components/victory";
import { createIdentityComponent } from "../../../../../src/core/domain/entities/player";
import {
  freshFoxCubState,
  freshPufferfishState,
  freshWhiteCatState,
} from "../../../../../src/game/mechanisms/roles/animal_dream/state";
import { installAnimalRoster } from "../../../../../src/game/mechanisms/roles/animal_dream/roster";
import { setWolfBeautyState } from "../../../../../src/game/mechanisms/roles/wolf_beauty/ports";
import { setBearState } from "../../../../../src/game/mechanisms/roles/bear/ports";

export const animalInternalConfig = () => ({
  boardSize: 12,
  enableSheriff: true,
  animalDream: { policy: "awa_animal_dream_v1", eliminationPriority: "awa_wolf_priority_v1" },
  whiteCat: { skippedVotePolicy: "awa_wait_for_actual_exile_v1" },
  pufferfish: { ballotPolicy: "awa_final_ballot_v1" },
  bear: { signalPolicy: "netease_dawn_live_v1" },
  wolfBeauty: { deathLinkPolicy: "awa_exile_poison_v1" },
  roleSetups: [
    { role: "wolf", count: 3 },
    { role: "wolf_beauty", count: 1 },
    { role: "villager", count: 4 },
    { role: "white_cat", count: 1 },
    { role: "fox_cub", count: 1 },
    { role: "bear", count: 1 },
    { role: "pufferfish", count: 1 },
  ],
  winConditions: ["slaughter_side"],
  hooks: { onDaybreak: false, onPreElection: true, onPreVote: true, onPerSpeechGap: false },
  selfDestruct: { enabledWindows: ["on_pre_election", "on_pre_vote"] },
  tieBreaker: {
    sheriffVote: "no_elimination",
    wolfKillVote: "min_id",
    exileVote: "no_elimination",
  },
  voting: { exilePolicy: "awa_one_pk_v1" },
  disclosure: { deathRevealPolicy: "awa_hidden_v1" },
  lastWords: { policy: "awa_initial_wave_v1" },
  sheriff: {
    electionPolicy: "awa_nomination_offstage_pk_v1",
    badgePolicy: "awa_holder_choice_v1",
    voteWeight: 1.5,
  },
});
/** Raw component fixture: no Profile initialization, public board loading, PM, transport or replay. */
export function animalRosterFixture(
  beforeInstall?: (world: World) => void,
  install: (
    world: World,
    config: ReturnType<typeof animalInternalConfig>,
  ) => void = installAnimalRoster,
) {
  const world = new World(),
    roles = [
      "wolf_beauty",
      "wolf",
      "wolf",
      "wolf",
      "villager",
      "villager",
      "villager",
      "villager",
      "white_cat",
      "fox_cub",
      "bear",
      "pufferfish",
    ] as const;
  for (const [index, roleId] of roles.entries()) {
    const id = world.createEntity(),
      camp = index < 4 ? Camp.Wolf : Camp.Good,
      role = createRoleComponent(roleId as Role, camp);
    if (roleId === "white_cat")
      (role.privateState as Record<string, unknown>).whiteCat = freshWhiteCatState();
    if (roleId === "fox_cub")
      (role.privateState as Record<string, unknown>).foxCub = freshFoxCubState();
    if (roleId === "pufferfish")
      (role.privateState as Record<string, unknown>).pufferfish = freshPufferfishState();
    if (roleId === "wolf_beauty")
      setWolfBeautyState(role, { targetId: null, lastActedDay: null, history: [] });
    if (roleId === "bear") setBearState(role, { history: [] });
    world.addComponent(id, COMPONENT.Role, role);
    world.addComponent(id, COMPONENT.Camp, createCampComponent(camp));
    world.addComponent(id, COMPONENT.Alive, createAliveComponent());
    world.addComponent(id, COMPONENT.VotingRight, createVotingRightComponent());
    world.addComponent(id, COMPONENT.Identity, createIdentityComponent(id, id, `p${id}`));
    world.addComponent(
      id,
      COMPONENT.Victory,
      createVictoryComponent([{ kind: "faction", faction: camp }]),
    );
  }
  beforeInstall?.(world);
  const config = animalInternalConfig();
  install(world, config);
  return {
    world,
    config,
    role: (id: number) => world.getComponent(id, COMPONENT.Role)!,
    life: (id: number) => world.getComponent(id, COMPONENT.Alive)!,
  };
}

/**
 * 负责构造猎魔人测试的候选、固定板子及显式玩家／标记数据。输入为变体、语言和种子选择；输出保留原数组、库存参数与配置身份。发牌可构造输入身份，期望结果仍为外部手写数据，不运行对局／模型或改变 oracle 算法。
 */
import {
  createCampComponent,
  createAliveComponent,
  createStatusMarksComponent,
  createVotingRightComponent,
  createBadgeComponent,
} from "../../../../../src/game/observation/component-presentation";
import "../../../../../src/app/bootstrap";
import { Role } from "../../../../../src/core";
import { DEMON_HUNTER_ROLE } from "../../../../../src/game/mechanisms/roles/demon_hunter/state-slot";
import { WinCondition } from "../../../../../src/core";
import { ActionWindow } from "../../../../../src/core";
import { WitchSelfHealRule } from "../../../../../src/core";
import type { BoardConfig } from "../../../../../src/core";
import { DEMON_HUNTER_POLICY } from "../../../../../src/game/mechanisms/roles/demon_hunter/state-slot";
import { World } from "../../../../../src/core";
import { Camp } from "../../../../../src/core";
import { COMPONENT } from "../../../../../src/core";
import { createRoleComponent } from "../../../../../src/game/observation/role-presentation";

import { createVictoryComponent } from "../../../../../src/core";

import { createRandom } from "../../../../../src/core";
import type { ToolName } from "../../../../../src/core";
import { createIdentityComponent } from "../../../../../src/core/domain/entities/player";
import { installInitialRoster } from "../../../../../src/core/domain/initial_roster";
import { ConditionRegistry } from "../../../../../src/core/domain/registries/condition_registry";
import { DamageResolutionSystem } from "../../../../../src/core/domain/systems/damage_resolution_system";
import { PhaseManager } from "../../../../../src/game/engine/phase_manager";
import { ToolGateway } from "../../../../../src/game/gateway/tool_gateway";
import { ActionValidator } from "../../../../../src/game/gateway/action_validator";
import { RoleCatalog } from "../../../../../src/game/mechanisms/roles/catalog";
import {
  getDefaultRoleCatalog,
  getDefaultRoleContributions,
  createRoleCatalog,
} from "../../../../../src/game/mechanisms/roles/role-catalog-assembly";
import { createDefaultRoleRegistry } from "../../../../../src/game/mechanisms/roles/permissions";
import { getDefaultWinConditionRegistry } from "../../../../../src/game/mechanisms";
import { ToolValidationRuleRegistry } from "../../../../../src/game/mechanisms/validation/tool_validation_rule_registry";
import { installDemonHunter } from "../../../../../src/game/mechanisms/roles/demon_hunter/authority";
import { freshDemonHunterState } from "../../../../../src/game/mechanisms/roles/demon_hunter/state-slot";
import { DEMON_HUNTER_TOOL_RULE } from "../../../../../src/game/mechanisms/roles/demon_hunter/validation_rules";

export function demonHunterDeck(size: 6 | 12): Role[] {
  return size === 6
    ? [Role.Wolf, Role.Wolf, Role.Villager, Role.Seer, Role.Witch, DEMON_HUNTER_ROLE as Role]
    : [
        Role.Wolf,
        Role.Wolf,
        Role.Wolf,
        Role.Villager,
        Role.Villager,
        Role.Villager,
        Role.Villager,
        Role.Seer,
        Role.Witch,
        Role.Hunter,
        Role.Guard,
        DEMON_HUNTER_ROLE as Role,
      ];
}

export function demonHunterBoard(size: 6 | 12, goal = WinCondition.SlaughterCity): BoardConfig {
  const deck = demonHunterDeck(size);
  return {
    boardSize: size,
    enableSheriff: size === 12,
    winConditions: [goal],
    roleSetups: [...new Set(deck)].map((role) => ({
      role,
      count: deck.filter((r) => r === role).length,
    })),
    hooks: { onPreElection: true, onPreVote: true, onDaybreak: false, onPerSpeechGap: false },
    selfDestruct: { enabledWindows: [ActionWindow.OnPreElection, ActionWindow.OnPreVote] },
    seer: { targetPolicy: "awa_alive_v1", actionPolicy: "awa_required_when_legal_v1" },
    witch: {
      canSelfHeal: WitchSelfHealRule.Disabled,
      knifeVisibility: "awa_with_heal_v1",
      potionPolicy: "awa_one_native_v1",
    },
    tieBreaker: {
      wolfKillVote: "min_id",
      exileVote: "min_id",
      ...(size === 12 ? { sheriffVote: "min_seat" as const } : {}),
    },
    voting: { exilePolicy: "awa_direct_v1" },
    disclosure: { deathRevealPolicy: "awa_hidden_v1" },
    lastWords: { policy: "awa_initial_wave_v1" },
    ...(size === 12
      ? {
          guard: { repeatPolicy: "netease_consecutive_nights_v1" as const },
          hunter: { deathActionPolicy: "awa_knife_or_exile_v1" as const },
          sheriff: {
            electionPolicy: "awa_final_candidates_v1" as const,
            badgePolicy: "awa_next_seat_v1" as const,
            voteWeight: 1.5,
          },
        }
      : {}),
    ...{ demonHunter: { policy: DEMON_HUNTER_POLICY } },
  };
}

export function demonHunterFixture(
  size: 6 | 12 = 6,
  goal = WinCondition.SlaughterCity,
  locale: "zh-CN" | "en" = "zh-CN",
  damage = new DamageResolutionSystem(),
  faultPlan?: unknown,
) {
  const world = new World(locale),
    config = demonHunterBoard(size, goal),
    deck = demonHunterDeck(size);
  const catalog = createRoleCatalog({
    contributions: [
      ...getDefaultRoleContributions().filter((p) => p.metadata.role !== Role.DemonHunter),
      {
        metadata: {
          role: DEMON_HUNTER_ROLE as Role,
          camp: Camp.Good,
          goodSide: "god",
          label: "Demon Hunter candidate",
          skillBrief: "Candidate",
        },
        runtime: { validationRules: { ["demon_hunt" as ToolName]: DEMON_HUNTER_TOOL_RULE } },
        presentation: { kind: "custom" },
      },
    ],
  });
  for (const kind of deck) {
    const id = world.createEntity(),
      camp = kind === Role.Wolf ? Camp.Wolf : Camp.Good,
      role = createRoleComponent(kind, camp, locale);
    if (String(kind) === DEMON_HUNTER_ROLE)
      (role.privateState as Record<string, unknown>).demonHunter = freshDemonHunterState();
    else getDefaultRoleCatalog().applyRuntime(role, { boardConfig: config, locale, world });
    world.addComponent(id, COMPONENT.Identity, createIdentityComponent(id, id, String(id)));
    world.addComponent(id, COMPONENT.Role, role);
    world.addComponent(id, COMPONENT.Camp, createCampComponent(camp, locale));
    world.addComponent(
      id,
      COMPONENT.Victory,
      createVictoryComponent([{ kind: "faction", faction: camp }]),
    );
    world.addComponent(id, COMPONENT.Alive, createAliveComponent(true, locale));
    world.addComponent(id, COMPONENT.StatusMarks, createStatusMarksComponent(locale));
    world.addComponent(id, COMPONENT.VotingRight, createVotingRightComponent(1, true, locale));
    world.addComponent(id, COMPONENT.Badge, createBadgeComponent(false, false, locale));
  }
  installInitialRoster(world);
  installDemonHunter(world, config);
  const gateway = new ToolGateway(
    new ActionValidator(new ToolValidationRuleRegistry(undefined, catalog)),
  );
  const phaseManager = new PhaseManager(
    world,
    config,
    gateway,
    createDefaultRoleRegistry(catalog),
    new ConditionRegistry(getDefaultWinConditionRegistry()),
    damage,
    createRandom("demon-night-candidate"),
    { faultPlan },
  );
  return {
    world,
    config,
    phaseManager,
    gateway,
    damage,
    demonId: size,
    witchId: size === 6 ? 5 : 9,
    hunterId: size === 12 ? 10 : null,
  };
}

/**
 * 负责馥郁 authority 测试的固定组件 roster 和原生 Pair 资源构造。
 * 输入为原安装／夜 callback；输出是同一 World、事件、选择 helper 和受控生命变更。
 * 字面角色／状态是 fixture 设置而非生产规则 oracle；Pair 别名、容器写入 LHS 时点保持。
 * 实例安装入口迁共享 owner，但不运行 profile、流水线、传输或模型。
 */
import { createAliveComponent, createCampComponent } from "../../../../../src/game/observation/component-presentation";
import { World } from "../../../../../src/core/domain/world";
import { Role, Camp } from "../../../../../src/core/domain/identity";
import { COMPONENT } from "../../../../../src/core/domain/components/names";
import { type AliveComponent } from "../../../../../src/core/domain/components/alive";
import { type RoleComponent } from "../../../../../src/core/domain/components/role";
import { createRoleComponent } from "../../../../../src/game/observation/role-presentation";

import { createIdentityComponent } from "../../../../../src/core/domain/entities/player";
import { createVictoryComponent } from "../../../../../src/core/domain/components/victory";
import type { GameEvent } from "../../../../../src/core/domain/events";
import { freshFragrantState } from "../../../../../src/game/mechanisms/roles/fragrant_pair_seer/fragrant-state-slot";
import { freshPairSeerState } from "../../../../../src/game/mechanisms/roles/fragrant_pair_seer/state";
import { installNativeAbility } from "../../../../../src/game/mechanisms/roles/ability_changes";
import {
  installFragrantPairAuthority,
  beginFragrantNight,
  openFragrantBindChoice,
  openPairCheckChoice,
} from "../../../../../src/game/mechanisms/roles/fragrant_pair_seer/authority";
/** 构造固定角色 roster 与原生双验资源供 authority 单元测试使用；不初始化 profile、判断板子支持或运行流水线、传输和复现。 */
export function fragrantPairOwnerFixture(
  beforeInstall?: (role: RoleComponent) => void,
  nightHook?: () => boolean,
) {
  const world = new World(),
    events: GameEvent[] = [];
  const roles = [
    Role.FragrantPhantom,
    Role.Wolf,
    Role.Wolf,
    Role.Wolf,
    Role.AwakenedSeer,
    Role.Witch,
    Role.Hunter,
    Role.Guard,
    Role.Villager,
    Role.Villager,
    Role.Villager,
    Role.Villager,
  ];
  for (const [index, roleId] of roles.entries()) {
    const id = world.createEntity(),
      camp = index < 4 ? Camp.Wolf : Camp.Good,
      role = createRoleComponent(roleId, camp);
    if (id === 1) (role.privateState as Record<string, unknown>).fragrant = freshFragrantState();
    if (id === 5)
      (role.privateState as Record<string, unknown>).pairSeer = installNativeAbility(
        role,
        "pair_check",
        freshPairSeerState(),
      );
    world.addComponent(id, COMPONENT.Role, role);
    world.addComponent(id, COMPONENT.Camp, createCampComponent(camp));
    world.addComponent(id, COMPONENT.Alive, createAliveComponent());
    world.addComponent(id, COMPONENT.Identity, createIdentityComponent(id, id, `p${id}`));
    world.addComponent(
      id,
      COMPONENT.Victory,
      createVictoryComponent([{ kind: "faction", faction: camp }]),
    );
  }
  // roster 已按字面顺序写入后才调用测试钩子，再安装 authority；抛错不回滚此前组件写入。
  beforeInstall?.(world.getComponent(5, COMPONENT.Role)!);
  installFragrantPairAuthority(world, events, 1, 5);
  let current = true,
    draws = 0;
  const random = {
      next: () => {
        draws++;
        return 0.5;
      },
    },
    isCurrent = () => current && (nightHook?.() ?? true);
  const open = (day = 1) => beginFragrantNight(world, day, random, isCurrent);
  const kill = (...ids: number[]) => {
    for (const id of ids) world.getComponent(id, COMPONENT.Alive)!.alive = false;
  };
  const role = (id: number) => world.getComponent(id, COMPONENT.Role)!;
  // helper 驱动真实选择提交，不从生产结果推导期望；测试须另写独立字面断言。
  const choices = (pair: number[] | null = [9, 10]) => {
    openFragrantBindChoice(world, 1).commit(pair);
    openPairCheckChoice(world, 1).commit([5, 6]);
  };
  return {
    world,
    events,
    open,
    kill,
    role,
    choices,
    random,
    isCurrent,
    stale: () => {
      current = false;
    },
    fresh: () => {
      current = true;
    },
    draws: () => draws,
  };
}

/**
 * 负责驱动夜贵族子系统的原 World fixture、有界夜选择、伤害和关闭。输入为脚本步骤、回调与资源请求，输出为原受控轨迹、句柄及边界响应。测试保留字面行动和失败预期；不运行完整对局或传输，也不引入付费模型。
 */
import { createAliveComponent, createCampComponent } from "../../../../../src/game/observation/component-presentation";
import { World } from "../../../../../src/core/domain/world";
import { COMPONENT } from "../../../../../src/core/domain/components/names";
import { Role, Camp } from "../../../../../src/core/domain/identity";
import { createRoleComponent } from "../../../../../src/game/observation/role-presentation";
import { type AliveComponent } from "../../../../../src/core/domain/components/alive";

import { createVictoryComponent } from "../../../../../src/core/domain/components/victory";
import { createIdentityComponent } from "../../../../../src/core/domain/entities/player";
import {
  createNobleState,
  createSecretBodyState,
} from "../../../../../src/game/mechanisms/roles/noble_secret_body/state";
import {
  installNobleBodyAuthority,
  beginNobleBodyNight,
  openSecretBodyChoice,
  openServantChoice,
  expireServantAtNightEnd,
  resolveSecretBodyDamage,
  closeNobleBodyNight,
} from "../../../../../src/game/mechanisms/roles/noble_secret_body/authority";
/** Explicit subsystem fixture. Surrogate existing cards prove original-object ownership;
 * this does not register the two planned roles or pretend to run their game rules. */
export function nobleBodyAuthorityFixture() {
  const world = new World(),
    roles = [];
  for (let id = 1; id <= 6; id++) {
    const actual = world.createEntity(),
      camp = id === 1 ? Camp.Wolf : Camp.Good,
      role = createRoleComponent(id === 1 ? Role.Wolf : Role.Villager, camp);
    if (id === 1) (role.privateState as Record<string, unknown>).noble = createNobleState();
    if (id === 2)
      (role.privateState as Record<string, unknown>).secretBody = createSecretBodyState();
    world.addComponent(actual, COMPONENT.Role, role);
    world.addComponent(
      actual,
      COMPONENT.Identity,
      createIdentityComponent(actual, actual, `Synthetic ${actual}`),
    );
    world.addComponent(actual, COMPONENT.Camp, createCampComponent(camp));
    world.addComponent(
      actual,
      COMPONENT.Victory,
      createVictoryComponent([{ kind: "faction", faction: camp }]),
    );
    world.addComponent(actual, COMPONENT.Alive, createAliveComponent());
    roles.push(role);
  }
  installNobleBodyAuthority(world, 1, 2);
  const life = (id: number) => world.getComponent(id, COMPONENT.Alive)!;
  const finish = (day: number) => {
    expireServantAtNightEnd(world, day);
    closeNobleBodyNight(world, day, "normal");
    return resolveSecretBodyDamage(world, day, {});
  };
  const night = (
    day: number,
    bodyTarget: number | null = null,
    nobleTarget: number | null = null,
  ) => {
    beginNobleBodyNight(world, day, () => true);
    openSecretBodyChoice(world, day).commit(bodyTarget);
    if (day >= 2) openServantChoice(world, day).commit(nobleTarget);
  };
  return { world, roles, life, finish, night };
}

/**
 * 构造蚀日者有界机制测试的显式 World、组件、Catalog 与初始座位。输入为原配置、组件及调用方字段，输出为原 fixture；手写断言和身份快照由测试持有，不运行完整对局、传输或生产规则验证器。
 */
import {
  createAliveComponent,
  createBadgeComponent,
  createCampComponent,
  createStatusMarksComponent,
  createVotingRightComponent,
} from "../../../../../src/game/observation/component-presentation";
import type { LastWolfBlastPolicy } from "@ai-werewolf-arena/game-contract";
import { World } from "../../../../../src/core/domain/world";
import { Role } from "../../../../../src/core/domain/identity";
import { COMPONENT } from "../../../../../src/core/domain/components/names";
import { createRoleComponent } from "../../../../../src/game/observation/role-presentation";

import { createVictoryComponent } from "../../../../../src/core/domain/components/victory";
import { createIdentityComponent } from "../../../../../src/core/domain/entities/player";
import { installInitialRoster } from "../../../../../src/core/domain/initial_roster";
import { RoleCatalog } from "../../../../../src/game/mechanisms/roles/catalog";
import {
  getDefaultRoleCatalog,
  getDefaultRoleContributions,
  createRoleCatalog,
} from "../../../../../src/game/mechanisms/roles/role-catalog-assembly";
import { RED_MOON_ROLE_PROFILE } from "../../../../../src/game/mechanisms/roles/red_moon_apostle/profile";
import { installDemonHunter } from "../../../../../src/game/mechanisms/roles/demon_hunter/authority";
import { redMoonTwelveConfig } from "../../../../../src/runtime/scenarios/red_moon_twelve";

export function redMoonCandidateWorld(policy: LastWolfBlastPolicy = "ends_game") {
  const world = new World();
  const config = structuredClone(redMoonTwelveConfig);
  config.redMoon!.lastWolfBlastPolicy = policy;
  const catalog = createRoleCatalog({
    contributions: [
      ...getDefaultRoleContributions().filter(
        (p) => String(p.metadata.role) !== "red_moon_apostle",
      ),
      RED_MOON_ROLE_PROFILE,
    ],
  });
  const roles = config.roleSetups.flatMap((row) => Array<Role>(row.count).fill(row.role));
  const ids = roles.map((kind, i) => {
    const id = world.createEntity();
    const role = createRoleComponent(kind, catalog.getCamp(kind), world.locale);
    catalog.applyRuntime(role, { boardConfig: config, locale: world.locale, world });
    world.addComponent(id, COMPONENT.Identity, createIdentityComponent(id, i + 1, "player-" + id));
    world.addComponent(id, COMPONENT.Role, role);
    world.addComponent(id, COMPONENT.Camp, createCampComponent(role.camp, world.locale));
    world.addComponent(
      id,
      COMPONENT.Victory,
      createVictoryComponent([{ kind: "faction", faction: role.camp }]),
    );
    world.addComponent(id, COMPONENT.Alive, createAliveComponent(true, world.locale));
    world.addComponent(id, COMPONENT.StatusMarks, createStatusMarksComponent(world.locale));
    world.addComponent(
      id,
      COMPONENT.VotingRight,
      createVotingRightComponent(1, true, world.locale),
    );
    world.addComponent(id, COMPONENT.Badge, createBadgeComponent(false, false, world.locale));
    return id;
  });
  installInitialRoster(world);
  installDemonHunter(world, config);
  return { world, config, ids, catalog };
}
